<script setup lang="ts">
const props=defineProps<{warehouseId:number}>()
const {t}=useI18n(),{bizErrorMessage}=useBizError()
const data=ref<any>(null),error=ref(''),loading=ref(false)
let generation=0
const load=async()=>{const seq=++generation;data.value=null;error.value='';loading.value=true;const result=await httpRequest<any>('/api/warehouse/inventory/history/series',{params:{warehouse_id:props.warehouseId,stock_types:'onhand'},headers:warehouseHeaders(props.warehouseId),onError:e=>{if(seq===generation)error.value=bizErrorMessage(e)}});if(seq===generation){data.value=result;loading.value=false}}
watch(()=>props.warehouseId,load);onMounted(load);onBeforeUnmount(()=>generation++)
const chart=computed(()=>stockTrendChart(data.value?.series||[]))
</script>
<template><WCard class="stock-trend"><header><h2>{{t('inventory-analysis.stock-trend')}}</h2><span v-if="data">{{data.from}} — {{data.to}}</span></header><p>{{t('inventory-analysis.stock-trend-help')}}</p><WAlert v-if="error" tone="block" :title="error"/><WEmptyState v-else-if="loading" compact :title="t('common.status.loading')"/><div v-else-if="chart" class="trend-body"><div class="plot"><div class="ticks"><span>{{chart.max.toLocaleString()}}</span><span>{{chart.min.toLocaleString()}}</span></div><svg viewBox="0 0 600 180" role="img" :aria-label="t('inventory-analysis.stock-trend')" preserveAspectRatio="none"><path d="M0 20H600 M0 90H600 M0 160H600" stroke="#EDEFF3" fill="none"/><path :d="chart.line" stroke="#7855FE" stroke-width="2" fill="none" vector-effect="non-scaling-stroke"/><circle v-for="point in chart.points" :key="point.date" :cx="point.x" :cy="point.y" r="2" fill="#7855FE"><title>{{point.date}}: {{point.total}}</title></circle></svg><div class="dates"><span>{{data.from}}</span><span>{{data.to}}</span></div></div><div class="latest"><span>{{t('goods.ui.onhand')}}</span><strong>{{chart.last==null?'—':Number(chart.last).toLocaleString()}}</strong><span>{{t('inventory-analysis.pieces')}}</span></div></div><WEmptyState v-else compact :title="t('inventory.history.none')"/></WCard></template>
<style scoped>
.stock-trend :deep(.w-card__body){padding:16px 24px 20px}header{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}h2{margin:0;font-size:16px;line-height:24px;font-weight:600}header>span,p{font-size:12px;line-height:18px;color:var(--w-text-3)}p{margin:8px 0 12px}.trend-body{display:flex;align-items:center;gap:32px}.plot{flex:1;min-width:0;display:grid;grid-template-columns:44px minmax(0,1fr);gap:0 8px}.ticks{display:flex;flex-direction:column;justify-content:space-between;padding:14px 0 20px;font-size:12px;line-height:18px;color:var(--w-text-3);text-align:right}svg{width:100%;height:180px;overflow:visible}.dates{grid-column:2;display:flex;justify-content:space-between;font-size:12px;line-height:18px;color:var(--w-text-3)}.latest{display:flex;align-items:baseline;gap:6px;font-size:13px;color:var(--w-text-2)}.latest strong{font-size:20px;line-height:28px;font-weight:600;color:var(--w-text-1)}@media(max-width:600px){.trend-body{flex-direction:column;align-items:stretch;gap:16px}.latest{justify-content:flex-end}}
</style>
